/**
 * Reorder rows of a tabular dataset by the values in its "name" column,
 * arranging them according to the sequence given in orderList.
 *
 * @param {Array<Object>} data - Array of row objects.
 * @param {Array} orderList - Array listing the desired sequence of name values.
 * @param {string} [nameColumn="name"] - Property name that stores the row's name.
 * @returns {Array<Object>} - New array of rows ordered according to orderList.
 */
export function reorderRowsByName(data, orderList, nameColumn = "name") {
  if (!Array.isArray(data)) throw new TypeError("data must be an array");
  if (!Array.isArray(orderList)) throw new TypeError("orderList must be an array");

  // Map each allowed name to its index in the order list
  const orderIndex = new Map();
  for (let i = 0; i < orderList.length; i++) orderIndex.set(orderList[i], i);

  // Pair rows with original index to preserve relative order for ties/unknowns
  const wrapped = data.map((row, i) => ({ row, originalIndex: i }));

  wrapped.sort((a, b) => {
    const aName = a.row[nameColumn];
    const bName = b.row[nameColumn];

    // If name not in order list, give it Infinity so it sorts after known names
    const ai = orderIndex.has(aName) ? orderIndex.get(aName) : Infinity;
    const bi = orderIndex.has(bName) ? orderIndex.get(bName) : Infinity;

    // Use d3-array ascending for numeric comparison; if equal, use original index
    const cmp = ascending(ai, bi);
    return cmp !== 0 ? cmp : ascending(a.originalIndex, b.originalIndex);
  });

  // Return sorted rows (unwrapped)
  return wrapped.map(w => w.row);
}
