  const rowsInSequence = [];
  const rowsNotInSequence = [];

  data.forEach(row => {
    const nameValue = row[nameColumn];
    if (sequenceIndexMap.has(nameValue)) {
      rowsInSequence.push(row);
    } else {
      rowsNotInSequence.push(row);
    }
