  const list = Immutable.List(lst0);

  if (list.size === 0) return Immutable.List();

  // Sort once (ascending). Comparator handles numbers and strings.
  const sorted = list.sort((a, b) => {
    if (a === b) return 0;
    return a < b ? -1 : 1;
