```javascript
/**
 * Extract values of a specified attribute from each item using underscore.js.
 *
 * @param {Array} items - Array of objects/items.
 * @param {String|Function} attribute - Attribute name (supports "a.b.c" paths) or a function(item) -> value.
 * @param {Object} [options] - Optional settings:
 *   - omitUndefined {Boolean} - if true, omit undefined/null values from the result (default: false).
 * @returns {Array} - Array of extracted values.
 *
 * Requires: underscore.js (the global "_" object).
 */
function extractAttributeValues(items, attribute, options) {
  options = options || {};
  var omitUndefined = !!options.omitUndefined;

  if (typeof _ === 'undefined') {
    throw new Error('underscore.js (_) is required');
  }
  if (!_.isArray(items)) {
    return [];
  }

  // helper to access nested path like "a.b.c"
  function getByPath(obj, path) {
    if (obj == null) return undefined;
    var parts = path.split('.');
    var cur = obj;
    for (var i = 0; i < parts.length; i++) {
      if (cur == null) return undefined;
      cur = cur[parts[i]];
    }
    return cur;
  }

  var result;
  if (_.isFunction(attribute)) {
    result = _.map(items, attribute);
  } else if (_.isString(attribute)) {
    result = _.map(items, function(item) {
      return getByPath(item, attribute);
    });
  } else {
    // unsupported attribute specifier
    return [];
  }

  return omitUndefined ? _.filter(result, function(v) { return v !== undefined && v !== null; }) : result;
}
```

