const { Matrix } = require('ml-matrix');

/**
 * Calculates the sum of the outer products of two sequences of numeric lists.
 * 
 * @param {Array<Array<number>>} seq1 - The first sequence of numeric lists.
 * @param {Array<Array<number>>} seq2 - The second sequence of numeric lists.
 * @returns {Matrix} - The resulting matrix from the sum of outer products.
 */
function sumOuterProducts(seq1, seq2) {
    // Validate input
    if (seq1.length !== seq2.length) {
        throw new Error('Both sequences must have the same length.');
    }

    let result = null;

    for (let i = 0; i < seq1.length; i++) {
        const vector1 = new Matrix(seq1[i]); // Create a column vector from seq1
        const vector2 = new Matrix(seq2[i]); // Create a column vector from seq2

        // Compute the outer product of vector1 and vector2
        const outerProduct = vector1.mmul(vector2.transpose());

        // Add the outer product to the result
        if (result === null) {
            result = outerProduct;
        } else {
            result.add(outerProduct);
        }
    }

    return result;
}

