```javascript
// topNIndicesByVar0(lst0, N)
// - lst0: array of objects (each should have a numeric `var0` property)
// - N: number of top elements to retrieve
// Returns: array of indices (into lst0) of the N elements with largest var0 values,
//          sorted descending by var0 (largest first).
function topNIndicesByVar0(lst0, N) {
  if (!Array.isArray(lst0)) throw new TypeError('lst0 must be an array');
  const n = lst0.length;
  if (n === 0 || N <= 0) return [];
  N = Math.min(Math.floor(N), n);

  // Build array of indices 0..n-1
  const idx = new Array(n);
  for (let i = 0; i < n; i++) idx[i] = i;

  // Comparator that compares indices by lst0[index].var0 (ascending)
  const cmp = (ia, ib) => {
    const a = lst0[ia] && typeof lst0[ia] === 'object' ? lst0[ia].var0 : undefined;
    const b = lst0[ib] && typeof lst0[ib] === 'object' ? lst0[ib].var0 : undefined;
    // Treat undefined/null as -Infinity so they are treated smallest
    const va = (a == null) ? -Infinity : +a;
    const vb = (b == null) ? -Infinity : +b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
  };

  // Obtain quickselect function (browser global or Node require)
  const qs = (typeof quickselect !== 'undefined') ? quickselect
           : (typeof require !== 'undefined' ? require('quickselect') : null);
  if (!qs) {
    throw new Error('quickselect not found. In Node: npm install quickselect and ensure require("quickselect") works. In browser: include quickselect and expose global `quickselect`.');
  }

  // Partition so that elements with index >= k are the top N largest values
  const k = n - N;
  qs(idx, k, 0, n - 1, cmp);

  // Extract the top-N slice (indices in idx[k..n-1]) and sort them descending by var0
  const result = idx.slice(k).sort((ia, ib) => {
    // reverse cmp for descending
    return cmp(ib, ia);
  });

  return result;
}
