    throw new Error("df0 must be a sanfojs DataFrame with a toJSON() method.");
  }

  // Get rows as array of objects: [{colA: valA, colB: valB, ...}, ...]
  const rows = df0.toJSON();
  const sums = new Map();

  for (const row of rows) {
    const key = row[col0];
    let val = row[col1];

    // normalize value to number (treat non-numeric / missing as 0)
    if (val === null || val === undefined || val === "") {
      val = 0;
    } else {
      val = Number(val);
      if (Number.isNaN(val)) val = 0;
    }

    sums.set(key, (sums.get(key) || 0) + val);
  }

  // Build result rows
  const resultRows = [];
  for (const [key, total] of sums.entries()) {
    resultRows.push({ [col0]: key, [outColName]: total });
  }

