 * by applying a time-based window of duration var0 over the timestamps in column str0.
 *
 * @param {DataFrame} df0 - The input DataFrame
 * @param {string} str0 - The column name of the timestamps
 * @param {number} var0 - The duration of the time-based window in milliseconds
 * @returns {DataFrame} A new DataFrame with the moving average
 */
function movingAverage(df0, str0, var0) {
  // Ensure the input DataFrame is a Pond.js DataFrame
  const df = new DataFrame(df0);

  // Convert the timestamp column to a Date type
  df[str0] = df[str0].map((x) => new Date(x));

  // Sort the DataFrame by the timestamp column
