  if (typeof pond === 'undefined' || !pond.TimeSeries) {
    throw new Error('pond.js is required and must be available as global "pond".');
  }

  // parse var0 into milliseconds (supports number or simple string like "5s","10m","2h","1d","100ms")
  function parseDuration(d) {
    if (typeof d === 'number' && isFinite(d)) return d;
    if (typeof d === 'string') {
      var m = d.match(/^(\d+(?:\.\d+)?)(ms|s|m|h|d)?$/);
      if (!m) throw new Error('Unsupported duration string: ' + d);
      var val = parseFloat(m[1]);
      var unit = m[2] || 'ms';
      switch (unit) {
        case 'ms': return val;
        case 's':  return val * 1000;
        case 'm':  return val * 60 * 1000;
        case 'h':  return val * 60 * 60 * 1000;
        case 'd':  return val * 24 * 60 * 60 * 1000;
        default: throw new Error('Unsupported duration unit: ' + unit);
      }
    }
    throw new Error('var0 must be a number (ms) or a string like "5s","10m","2h","1d","100ms".');
  }

  var windowMs = parseDuration(var0);

  // Normalize and validate rows: extract timestamp (ms) and numeric value
  var rows = (df0 || []).map(function (r) {
