    return !isNaN(r.ts) && !isNaN(r.value);
  });

  // Sort by timestamp ascending
  rows.sort(function (a, b) { return a.ts - b.ts; });

  // Sliding-window two-pointer approach (O(n))
  var points = []; // will hold [timestamp (ms), average]
  var start = 0;
  var sum = 0;
  for (var i = 0; i < rows.length; i++) {
    sum += rows[i].value;

    // advance start until rows[start].ts is inside the window (t - windowMs, t]
    while (start <= i && rows[start].ts < rows[i].ts - windowMs) {
      sum -= rows[start].value;
      start += 1;
    }

    var count = i - start + 1;
    var avg = count > 0 ? (sum / count) : NaN;
    points.push([rows[i].ts, avg]);
  }

  // Build and return a pond.TimeSeries object
  return new pond.TimeSeries({
    name: 'movingAverage',
    columns: ['time', 'movingAvg'],
    points: points
  });
