/**
 * Filters a table based on multiple conditions using Tablulator
 * @param {string} tableId - The ID of the table element to filter
 * @param {Object} conditions - Object containing filter conditions
 * @param {string} [conditions.column] - Column to filter on (optional if using columnName)
 * @param {string} [conditions.columnName] - Column name to filter on (alternative to column)
 * @param {string} [conditions.operator] - Filter operator ('=', '!=', '>', '<', '>=', '<=', 'contains', 'startsWith', 'endsWith')
 * @param {*} [conditions.value] - Value to filter by
 * @param {boolean} [conditions.caseSensitive=false] - Whether the filter should be case sensitive
 * @param {boolean} [conditions.exactMatch=false] - Whether to do exact matching (for text columns)
 * @param {boolean} [conditions.clearOtherFilters=true] - Whether to clear other filters before applying
 * @returns {Promise<void>} Resolves when filtering is complete
 */
function filterTableWithConditions(tableId, conditions) {
    return new Promise((resolve, reject) => {
        try {
            // Get the table instance
            const table = document.getElementById(tableId);

            if (!table) {
                throw new Error(`Table with ID '${tableId}' not found`);
            }

            // Initialize Tablulator if not already initialized
            if (!table.tablulator) {
                table.tablulator = new Tabulator(table, {
                    layout: "fitColumns",
                    // Add other default options if needed
                });
            }

            // Prepare the filter parameters
            const filterParams = {};

            // Determine which column to filter on
            let column;
            if (conditions.column) {
                column = conditions.column;
            } else if (conditions.columnName) {
                // Find column by name
                const columns = table.tablulator.getColumns();
                column = columns.find(col => col.header === conditions.columnName);
                if (!column) {
                    throw new Error(`Column with name '${conditions.columnName}' not found`);
                }
                column = column.field;
            } else {
                throw new Error('Either "column" or "columnName" must be specified in conditions');
            }

            // Set default operator if not specified
            const operator = conditions.operator || '=';

            // Set default case sensitivity
            const caseSensitive = conditions.caseSensitive !== false;

            // Set default exact match
            const exactMatch = conditions.exactMatch !== false;

            // Prepare the filter value
            let filterValue = conditions.value;

            // Apply the filter
            filterParams[column] = {
                filterType: 'text',
                test: (value) => {
                    // Handle different operators
                    switch (operator) {
                        case '=':
                            return exactMatch ?
                                value === filterValue :
                                value.toString().localeCompare(filterValue.toString(), undefined, { sensitivity: caseSensitive ? 'base' : 'accent' }) === 0;
                        case '!=':
                            return exactMatch ?
                                value !== filterValue :
                                value.toString().localeCompare(filterValue.toString(), undefined, { sensitivity: caseSensitive ? 'base' : 'accent' }) !== 0;
                        case '>':
                            return value > filterValue;
                        case '<':
                            return value < filterValue;
                        case '>=':
                            return value >= filterValue;
                        case '<=':
                            return value <= filterValue;
                        case 'contains':
                            return exactMatch ?
                                value.includes(filterValue) :
                                value.toString().includes(filterValue.toString());
                        case 'startsWith':
                            return exactMatch ?
                                value.startsWith(filterValue) :
                                value.toString().startsWith(filterValue.toString());
                        case 'endsWith':
                            return exactMatch ?
                                value.endsWith(filterValue) :
                                value.toString().endsWith(filterValue.toString());
                        default:
                            return false;
                    }
                }
            };

            // Clear other filters if requested
            if (conditions.clearOtherFilters) {
                table.tablulator.clearFilters();
            }

            // Apply the filter
            table.tablulator.setFilter(filterParams);

            // Resolve the promise
            resolve();
        } catch (error) {
            reject(error);
        }
    });
}

