# Multi-Condition Table Filter with Tabulator

Here's a self-contained JavaScript function that filters a Tabulator table based on multiple conditions:

```javascript
/**
 * Filters a Tabulator table based on multiple conditions
 * @param {Tabulator} table - The Tabulator table instance
 * @param {Array} conditions - Array of filter conditions
 *   Each condition should be: { field: string, type: string, value: any }
 *   Types: 'eq' (equal), 'ne' (not equal), 'like' (contains), 
 *          'gt' (greater than), 'lt' (less than), 'gte', 'lte'
 * @param {string} matchType - 'and' (all conditions) or 'or' (any condition)
 */
function filterTableByConditions(table, conditions, matchType = 'and') {
  if (!table || !conditions || conditions.length === 0) {
    table.clearFilter();
    return;
  }

  // Build filter function based on conditions
  const filterFunction = (row) => {
    const rowData = row.getData();

    const results = conditions.map(condition => {
      const { field, type, value } = condition;
      const cellValue = rowData[field];

      switch (type) {
        case 'eq':
          return cellValue == value;
        case 'ne':
          return cellValue != value;
        case 'like':
          return String(cellValue).toLowerCase().includes(String(value).toLowerCase());
        case 'gt':
          return cellValue > value;
        case 'lt':
          return cellValue < value;
        case 'gte':
          return cellValue >= value;
        case 'lte':
          return cellValue <= value;
        default:
          return true;
      }
    });

    // Apply match type logic
    return matchType === 'and' ? results.every(r => r) : results.some(r => r);
  };

  table.setFilter(filterFunction);
}

