 * @returns {Map} - A new Immutable Map with entries sorted by the highest number in each sequence
 */
function sortByMaxSequence(keyToSequenceMap) {
  // Convert input to Immutable Map if it isn't already
  const map = fromJS(keyToSequenceMap);

  // Get the max value for each sequence
  const maxValues = map.map((sequence) => {
    // Handle cases where sequence might not be an array or is empty
    if (!Array.isArray(sequence) || sequence.length === 0) {
      return -Infinity; // Treat empty sequences as having the smallest possible max
    }

    // Find the maximum number in the sequence
    const max = Math.max(...sequence.filter(item => typeof item === 'number'));
    return max;
  });

  // Combine original keys with their max values for sorting
  const entriesWithMax = map.entries().map(([key, sequence]) => {
    const maxValue = maxValues.get(key);
    return { key, maxValue };
