  // Sort entries by maxValue in descending order
  const sortedEntries = entriesWithMax.sort((a, b) => b.maxValue - a.maxValue);

  // Create new map with sorted entries
  return Map(sortedEntries.map(entry => [entry.key, map.get(entry.key)]));
}

