/**
 * Reorders a key-to-sequence mapping so entries are sorted in descending order
 * based on the highest number in each associated sequence.
 * 
 * @param {Object|Immutable.Map} mapping - A key-to-sequence mapping
 * @returns {Immutable.Map} - A new Map sorted by highest sequence value (descending)
 */
function reorderByHighestNumber(mapping) {
  // Convert to Immutable Map if not already
  const immutableMap = Immutable.Map.isMap(mapping) 
    ? mapping 
    : Immutable.Map(mapping);

  // Sort the entries by the maximum value in each sequence
  const sorted = immutableMap
    .entrySeq()
    .sortBy(([key, sequence]) => {
      // Get the maximum number from the sequence
      const maxValue = Immutable.Iterable.isIterable(sequence)
        ? sequence.max()
        : Math.max(...sequence);

      // Return negative value for descending sort
      return -maxValue;
    })
    .fromEntrySeq();

  return Immutable.Map(sorted);
}

