    if (typeof slasql.table === 'function') {
      // slasql.table({ columns, rows }) is a common factory pattern
      try { return slasql.table({ columns, rows }); } catch (e) { /* fall through */ }
    }
    if (typeof slasql.Table === 'function' && typeof slasql.Table.from === 'function') {
