  }

  // Extract index array (if any)
  const rawIndex = Array.isArray(table.index) ? table.index : null;

  if (!rawIndex || drop) {
    // No index present or user asked to drop -> simply return a copy (index becomes default 0..n-1)
    return createTable(columns, rows.map(r => r.slice()));
  }

  // rawIndex is an array with length equal to rows.length
  if (rawIndex.length !== rows.length) {
    throw new Error('resetIndex: length of table.index does not match number of rows.');
  }

  // Determine whether index is multi-level (each entry is array) or single-level
  const isMultiLevel = rawIndex.length > 0 && Array.isArray(rawIndex[0]);

  // Determine index column names: try table.indexNames, else use a default naming scheme
  let indexNames = Array.isArray(table.indexNames) ? table.indexNames.slice() : null;
