    }
  } else {
    // If provided indexNames count doesn't match, fall back to defaults
    const needed = isMultiLevel ? rawIndex[0].length : 1;
    if (indexNames.length !== needed) {
      indexNames = isMultiLevel ? rawIndex[0].map((_, i) => `index_${i}`) : ['index'];
    }
  }

