/**
 * Imputes missing values in a 2D dataset by replacing them with column means.
 * Missing values are represented as null, undefined, or NaN.
 * 
 * @param {Array<Array<number>>} data - 2D array where each sub-array is a column
 * @returns {Array<Array<number>>} New dataset with missing values replaced by column means
 */
function imputeColumnMeans(data) {
  // Handle edge cases
  if (!data || data.length === 0) {
    return data;
  }

  // Determine the number of rows (assuming rectangular data)
  const numRows = Math.max(...data.map(col => col.length));

  // Calculate the mean for each column, excluding missing values
  const columnMeans = data.map(column => {
    const nonMissingValues = column.filter(val => 
      val !== null && val !== undefined && !Number.isNaN(val)
    );

    if (nonMissingValues.length === 0) {
      return 0; // Default to 0 if all values in column are missing
    }

    const sum = nonMissingValues.reduce((acc, val) => acc + val, 0);
    return sum / nonMissingValues.length;
  });

  // Create new dataset with imputed values
  const imputedData = data.map((column, colIndex) => {
    return column.map(val => {
      // Replace missing values with column mean
      if (val === null || val === undefined || Number.isNaN(val)) {
        return columnMeans[colIndex];
      }
      return val;
    });
  });

  return imputedData;
}

