 * @returns {Array<Array<any>>} A new 2D array with missing numeric entries
 *                              replaced by their column mean (if available).
 *
 * Requires jStat to be loaded (global jStat with jStat.mean available).
 */
function imputeMissingByColumnMean(data) {
  if (typeof jStat === 'undefined' || typeof jStat.mean !== 'function') {
    throw new Error('jStat library not found. Please include jStat (with jStat.mean) before using this function.');
  }
  if (!Array.isArray(data)) {
    throw new TypeError('Input must be a two-dimensional array.');
  }

  const nRows = data.length;
  const nCols = nRows === 0 ? 0 : Math.max(...data.map(r => Array.isArray(r) ? r.length : 0));

  // Compute column means from non-missing numeric values
  const colMeans = new Array(nCols).fill(NaN);
  for (let c = 0; c < nCols; c++) {
    const vals = [];
    for (let r = 0; r < nRows; r++) {
      const row = data[r];
      if (!Array.isArray(row) || row.length <= c) continue;
      const v = row[c];
      if (typeof v === 'number' && Number.isFinite(v)) vals.push(v);
    }
    if (vals.length > 0) {
      colMeans[c] = jStat.mean(vals);
