            thousand = thousand || ",";
            decimal = decimal || ".";
            format = format || "%s%v";

            const negative = number < 0 ? "-" : "";
            const base = toFixed(Math.abs(number), precision);
            const integer = base.split('.')[0];
            const fractional = precision > 0 ? decimal + base.split('.')[1] : "";

            let formattedInteger = "";
            for (let i = integer.length; i > 0; i -= 3) {
                const chunk = integer.substring(Math.max(0, i - 3), i);
                formattedInteger = (formattedInteger ? chunk + thousand : chunk) + formattedInteger;
