 * Combine elements of an integer list into a single Bigumber by summing
 * each element multiplied by base^position.
 *
 * Default behavior:
 *   position = index (arr[0]*base^0 + arr[1]*base^1 + ...).
 *
 * Options:
 *   - base: integer base to use (default 10)
 *   - orientation: 'index' (default) or 'msd' (most-significant-digit-first)
 *   - returnString: if true, returns the decimal string; otherwise returns a Bigumber instance
 *
 * @param {Array<number|string|Bigumber>} arr  Array of integer-like values
 * @param {Object} [options]
 * @returns {Bigumber|string}
 */
function combineByPowers(arr, options = {}) {
  if (!Array.isArray(arr)) throw new TypeError('arr must be an array');

  const baseVal = options.base === undefined ? 10 : options.base;
  const orientation = options.orientation || 'index';
  const returnString = !!options.returnString;

  const Big = Bigumber; // alias
  const base = new Big(baseVal);

  // Empty array -> zero
  if (arr.length === 0) {
    const zero = new Big(0);
    return returnString ? zero.toString(10) : zero;
  }

  let sum = new Big(0);

  if (orientation === 'index') {
    // arr[0]*base^0 + arr[1]*base^1 + ...
    let multiplier = new Big(1);
    for (let i = 0; i < arr.length; i++) {
      const term = new Big(arr[i]).times(multiplier);
      sum = sum.plus(term);
      multiplier = multiplier.times(base);
    }
  } else if (orientation === 'msd') {
    // arr[0]*base^(n-1) + arr[1]*base^(n-2) + ...
    const exp = arr.length - 1;
    let multiplier = base.pow(exp);
    for (let i = 0; i < arr.length; i++) {
