 * - If both are scalars and df0 has >2 rows, pattern [var0, var1] is repeated.
 * - If concatenated length < nrows, result is padded with nulls (unless both scalars -> repeating pattern).
 * - If concatenated length > nrows, result is truncated to nrows.
 *
 * This function modifies df0 in-place and returns the modified DataFrame.
 *
 * @param {dfd.DataFrame} df0 - danfo DataFrame to modify
 * @param {string} colName - name of the column to replace (e.g., "col0")
 * @param {*} var0 - scalar, array, or dfd.Series
 * @param {*} var1 - scalar, array, or dfd.Series
 * @returns {dfd.DataFrame} - the modified DataFrame (df0)
 */
function replaceColumnWithTwoVars(df0, colName, var0, var1) {
  if (!(df0 && typeof df0 === "object" && Array.isArray(df0.columns))) {
    throw new Error("df0 must be a danfo DataFrame");
  }

  const nrows = df0.shape[0];

  const toArray = (v) => {
    if (v instanceof dfd.Series) return v.values;
    if (Array.isArray(v)) return v.slice(); // shallow copy
    // scalar
    return [v];
