      reject(new Error(`CSV parsing error: ${results.errors.join(', ')}`));
      return;
    }

    // If no data or column not found, return 0
    if (!results.data || results.data.length === 0) {
      resolve(0);
      return;
    }

    // Find the column index
    const columnIndex = results.meta.fields.indexOf(columnName);
    if (columnIndex === -1) {
      resolve(0); // Column not found
      return;
    }

    // Count matches
    let count = 0;
    for (const row of results.data) {
      // Handle different types of comparison
      if (value === null || value === undefined) {
        if (row[columnIndex] === null || row[columnIndex] === undefined) {
          count++;
        }
      } else if (typeof value === 'object') {
        // For objects, compare with JSON.stringify for deep comparison
        if (JSON.stringify(row[columnIndex]) === JSON.stringify(value)) {
          count++;
        }
      } else {
