 * Sort each inner list in nestedLists according to orderMapping.
 * - nestedLists: Array of arrays or Immutable List of Lists
 * - orderMapping: Immutable Map, plain object (value->rank), or array (ordered values)
 * Returns an Immutable List of Lists (use .toJS() if you want plain arrays).
 */
function sortNestedListsByMapping(nestedLists, orderMapping) {
  // Normalize nestedLists to Immutable List of Lists
  const lists = isList(nestedLists)
    ? nestedLists
    : List((nestedLists || []).map(inner => List(inner || [])));

  // Normalize orderMapping into an Immutable Map of value -> rank (number)
  let mapping;
  if (isMap(orderMapping)) {
    mapping = orderMapping;
  } else if (Array.isArray(orderMapping)) {
    // array of values in desired order -> map each value to its index
    const obj = {};
    orderMapping.forEach((v, i) => { obj[v] = i; });
    mapping = Map(obj);
  } else {
    // assume plain object (value -> rank)
    mapping = Map(orderMapping || {});
  }

  const UNKNOWN_RANK = Number.MAX_SAFE_INTEGER;

  // For each inner list, attach rank and original index, sort by (rank, originalIndex),
  // then project back to values.
  return lists.map(inner =>
    inner
      .map((val, idx) => Map({ val, idx, rank: mapping.has(val) ? mapping.get(val) : UNKNOWN_RANK }))
