  let filtered = filter ? data.filter(filter) : data;

  // Step 2: Create a key function for tuples
  const keyFunction = key || ((tuple) => JSON.stringify(tuple));

  // Step 3: Group by tuple and count occurrences
  const grouped = d3.group(filtered, keyFunction);

  // Step 4: Convert to array of {tuple, count} objects
  let results = Array.from(grouped, ([tupleKey, items]) => ({
    tuple: JSON.parse(tupleKey),
