function mergeSequencesIntoPairs(sequence1, sequence2) {
  /**
   * Merges two input sequences by creating a new sequence of pairs,
   * where each pair contains elements from the same position in both sequences.
   * 
   * @param {Array} sequence1 - The first input sequence
   * @param {Array} sequence2 - The second input sequence
   * @returns {Array} An array of pairs [element1, element2]
