function findColumnsWithMissing(data, options = {}) {
  // options:
  //   missingValues: array of additional string tokens to treat as missing (default: ['NA','N/A','NULL','NaN','.','-'])
  //   treatWhitespaceOnlyAsMissing: boolean (default: true)
  const {
    missingValues = ['NA', 'N/A', 'NULL', 'NaN', '.', '-'],
    treatWhitespaceOnlyAsMissing = true
  } = options;

  // Normalize tokens for quick checking
  const tokenSet = new Set(missingValues.map(t => String(t).trim().toLowerCase()));

  // Accept either CSV string or array of row objects
  let rows;
  if (typeof data === 'string') {
    // requires d3.csvParse to be available (d3-dsv)
    rows = d3.csvParse(data);
  } else if (Array.isArray(data)) {
    rows = data;
  } else {
    throw new Error('data must be a CSV string or an array of objects (rows)');
  }

  // Determine column names. d3.csvParse returns an array with a .columns property.
  let columns;
  if (rows.columns && Array.isArray(rows.columns) && rows.columns.length > 0) {
    columns = rows.columns.slice();
  } else {
    const cols = new Set();
    rows.forEach(row => {
      Object.keys(row).forEach(k => cols.add(k));
    });
    columns = Array.from(cols);
  }

  // If no columns, return empty array
  if (columns.length === 0) return [];

  // Track whether each column has at least one missing value
  const hasMissing = {};
  columns.forEach(c => hasMissing[c] = false);

  // Scan rows; stop checking a column once it's known to have a missing value
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    // quickly stop early if all columns already flagged
    if (columns.every(c => hasMissing[c])) break;

    for (const col of columns) {
      if (hasMissing[col]) continue;
      const value = row[col];

      // Missing if null or undefined
      if (value === null || value === undefined) {
        hasMissing[col] = true;
        continue;
      }

      // Missing if numeric NaN
      if (typeof value === 'number' && Number.isNaN(value)) {
        hasMissing[col] = true;
        continue;
      }

      // Missing if string that is empty / whitespace-only (optional), or matches a missing token
      if (typeof value === 'string') {
        const trimmed = value.trim();
        if (treatWhitespaceOnlyAsMissing && trimmed === '') {
          hasMissing[col] = true;
          continue;
        }
        if (tokenSet.has(trimmed.toLowerCase())) {
          hasMissing[col] = true;
          continue;
        }
      }
    }
  }

  // Return list of columns that had missing values
  return columns.filter(c => hasMissing[c]);
}

