 *
 * @param {Object} tree                                - Root node of the trained tree (e.g. tree0)
 * @param {Array<string>} featureNames                 - Array of feature names (feature_names0)
 * @returns {Array<string>}                            - Array of human-readable rule strings
 */
function extractDecisionRules(tree, featureNames) {
