  };

  // Helpers to guess common property names
  function isLeafNode(node) {
    if (!node || typeof node !== 'object') return true;
    if (node.isLeaf === true || node.leaf === true) return true;
    // Some trees don't mark leaf but have no children
    if (node.left == null && node.right == null && !node.children && !node.branches) {
      // But if it has prediction/class/value, treat as leaf
      if (node.prediction != null || node.class != null || node.label != null || node.value != null || node.probs != null || node.distribution != null) {
        return true;
      }
      // If no feature/threshold either -> leaf
      if (getFeatureIndex(node) == null && getThreshold(node) == null && !hasChildrenArray(node)) {
        return true;
      }
    }
    return false;
