  function hasChildrenArray(node) {
    return Array.isArray(node.children) && node.children.length > 0;
  }

  function getChildren(node) {
    // prefer left/right
    if (!node || typeof node !== 'object') return [];
    if (node.left || node.right) {
      const children = [];
      if (node.left) children.push({ node: node.left, branch: 'left' });
      if (node.right) children.push({ node: node.right, branch: 'right' });
      return children;
    }
    if (Array.isArray(node.children)) {
      return node.children.map((c, i) => ({ node: c, branch: i }));
    }
    if (Array.isArray(node.branches)) {
      return node.branches.map((c, i) => ({ node: c, branch: i }));
    }
    // Some trees use 'childrenNodes' etc.
    const possibleChildrenKeys = ['childrenNodes', 'nodes', 'subtrees'];
    for (const key of possibleChildrenKeys) {
      if (Array.isArray(node[key])) return node[key].map((c, i) => ({ node: c, branch: i }));
    }
    return [];
  }

  function getFeatureIndex(node) {
    if (!node || typeof node !== 'object') return null;
    // Candidate property names
    const keys = ['feature', 'attribute', 'col', 'column', 'index', 'featureIndex', 'splitFeature'];
    for (const k of keys) {
      if (node[k] != null) {
        // If it's numeric index, return it
