          if (idx >= 0) return idx;
        }
      }
    }
    // Sometimes the split description is nested under split.feature
    if (node.split && typeof node.split === 'object') {
      const s = node.split;
      for (const k of ['feature', 'attribute', 'col']) {
        if (s[k] != null) {
          if (typeof s[k] === 'number') return s[k];
          if (typeof s[k] === 'string' && Array.isArray(featureNames)) {
