    return null;
  }

  function getThreshold(node) {
    if (!node || typeof node !== 'object') return null;
    const keys = ['threshold', 'splitValue', 'value', 'cut', 'cutPoint', 'split_value', 'split_value'];
    for (const k of keys) {
