        const r = {};
        for (const c of colNames) {
          r[c] = src[c] && i < src[c].length ? src[c][i] : undefined;
        }
        rows[i] = r;
      }
      return rows;
    }
    throw new Error('Unsupported data type for rows');
  };

  // Helper: get column names from various input types (preserve order)
  const colsFrom = (src) => {
    if (!src) return [];
    if (typeof src.columnNames === 'function') return src.columnNames();
    if (Array.isArray(src) && src.length > 0) return Object.keys(src[0]);
    if (typeof src === 'object') return Object.keys(src);
    return [];
  };

  const baseRows = rowsFrom(base);
  const addRows = rowsFrom(additions);

  // If additions provided, ensure number of rows matches base
  if (addRows) {
    if (baseRows.length !== addRows.length) {
      throw new Error('Base and additions must have the same number of rows');
    }
  }

  // Determine column order: base columns in their order, then addition-only columns in additions order
  const baseCols = colsFrom(base);
  const addCols = colsFrom(additions);
  const additionOnlyCols = addCols.filter((c) => !baseCols.includes(c));
  const initialOrder = [...baseCols, ...additionOnlyCols];

