  }

  // Use d3.group to group by the specified column
  const grouped = d3.group(df0, d => d[var0]);

  // Convert to hierarchical index structure
  const hierarchicalIndex = {
    index: Array.from(grouped.keys()),
    groups: Array.from(grouped.entries()).map(([key, values]) => ({
      level0: key,
      rows: values
    }))
