 *
 * @param {Array<Object>} records - Array of associative records (objects).
 * @param {string} key - The key in each record to base the ordering on.
 * @param {Array<*>} sequence - Array of values defining the desired order.
 * @param {Object} [options] - Optional settings.
 * @param {boolean} [options.unknownLast=true] - Put values not in sequence after known values if true; otherwise before.
 * @param {boolean} [options.reverse=false] - Reverse the final order if true.
 * @returns {Array<Object>} - A new array sorted according to the sequence.
 */
function sortBySequence(records, key, sequence, options) {
  options = Object.assign({ unknownLast: true, reverse: false }, options || {});

  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }
  if (typeof key !== 'string') {
    throw new TypeError('key must be a string');
  }
  if (!Array.isArray(sequence)) {
    throw new TypeError('sequence must be an array');
  }

  // Build mapping from value -> position index
  const position = new Map();
  for (let i = 0; i < sequence.length; i++) {
    position.set(sequence[i], i);
  }

  // Position assigned to unknown values:
  // If unknownLast is true, unknown values get index sequence.length (after all known)
  // If unknownLast is false, give them -1 (before all known)
  const unknownPos = options.unknownLast ? sequence.length : -1;

