    return require('kefit');
  } catch (e) {
    // Minimal shim used only for a couple of simple operations needed here.
    return {
      isEmpty: (arr) => !arr || arr.length === 0,
      clone: (arr) => (Array.isArray(arr) ? arr.slice() : []),
