  }
})();

/**
 * Combine a variable number of lists by following a sequence of indices.
 *
 * @param {Array<Array>} lists - Array of input lists (arrays).
 * @param {Array<number>} sequence - Array of 0-based indices indicating from which list to draw each next element.
 * @param {Object} [options]
 *   - cycleSequence {boolean} (default true): if true, cycle the sequence until no progress can be made.
 *   - strict {boolean} (default false): if true, invalid picks throw errors instead of being skipped.
 *   - appendRemaining {boolean} (default false): if true, append any remaining elements from lists at the end.
 *   - maxSteps {number} (default 1e6): safety cap on steps to prevent infinite loops.
 *
 * @returns {Array} Combined output array.
 */
function combineBySequence(lists, sequence, options) {
  if (!Array.isArray(lists)) throw new TypeError('lists must be an array of arrays');
  if (!Array.isArray(sequence)) throw new TypeError('sequence must be an array of indices');

  const opts = Object.assign(
    { cycleSequence: true, strict: false, appendRemaining: false, maxSteps: 1e6 },
    options || {}
  );

  // Clone buffers so original lists are not mutated
  const buffers = lists.map((l) => (Array.isArray(l) ? l.slice() : []));

  const out = [];
  if (sequence.length === 0) {
    if (opts.appendRemaining) buffers.forEach((b) => out.push(...b));
    return out;
  }

  let seqIdx = 0;
  let steps = 0;
  let iterationsSinceProgress = 0;

  // Helper to check if any buffers referenced in sequence still have elements
  const anyReferencedHasItems = () => {
    for (let i = 0; i < sequence.length; i += 1) {
      const idx = sequence[i];
      if (typeof idx === 'number' && idx >= 0 && idx < buffers.length && buffers[idx].length > 0) {
        return true;
      }
    }
    return false;
  };

  // If we're not cycling, just do one pass over the sequence
  if (!opts.cycleSequence) {
    for (let i = 0; i < sequence.length; i += 1) {
      const pick = sequence[i];
      if (typeof pick !== 'number' || pick < 0 || pick >= buffers.length) {
        if (opts.strict) throw new Error(`Invalid sequence index at position ${i}: ${pick}`);
        continue; // skip invalid index
      }
      const buf = buffers[pick];
      if (buf.length > 0) {
        out.push(buf.shift());
      } else if (opts.strict) {
        throw new Error(`Attempt to draw from empty list at sequence position ${i} (list ${pick})`);
      } // else skip empty pick
    }
  } else {
    // Cycle sequence until no progress is possible or until maxSteps
    while (true) {
      if (++steps > opts.maxSteps) {
        throw new Error('combineBySequence: reached maxSteps; possible infinite loop');
      }

      const pick = sequence[seqIdx];

      let madeProgress = false;
      if (typeof pick !== 'number' || pick < 0 || pick >= buffers.length) {
        if (opts.strict) throw new Error(`Invalid sequence index at cycle position ${seqIdx}: ${pick}`);
        // skip invalid index
      } else {
        const buf = buffers[pick];
        if (buf.length > 0) {
          out.push(buf.shift());
          madeProgress = true;
        } else if (opts.strict) {
          throw new Error(`Attempt to draw from empty list at sequence cycle position ${seqIdx} (list ${pick})`);
        }
      }

      if (madeProgress) {
        iterationsSinceProgress = 0;
      } else {
        iterationsSinceProgress += 1;
      }

      // If we've gone a full cycle without making progress, stop
      if (iterationsSinceProgress >= sequence.length) break;

      // If no referenced lists have any items, stop
      if (!anyReferencedHasItems()) break;

      seqIdx = (seqIdx + 1) % sequence.length;
    }
  }

  if (opts.appendRemaining) {
    buffers.forEach((b) => out.push(...b));
  }

  return out;
}

