  const config = {
    tolerance: options.tolerance || 1e-7,
    maxIterations: options.maxIterations || 100,
    lambdaInitial: options.lambdaInitial || 0.01,
    lambdaFactor: options.lambdaFactor || 10,
    ...options
  };

