    const f0 = equations(point);
    const J = [
      [0, 0],
      [0, 0]
    ];

    // Partial derivatives for x
    const xPlus = [point[0] + delta, point[1]];
    const fxPlus = equations(xPlus);
    J[0][0] = (fxPlus[0] - f0[0]) / delta;
    J[1][0] = (fxPlus[1] - f0[1]) / delta;

    // Partial derivatives for y
    const yPlus = [point[0], point[1] + delta];
    const fyPlus = equations(yPlus);
    J[0][1] = (fyPlus[0] - f0[0]) / delta;
    J[1][1] = (fyPlus[1] - f0[1]) / delta;

    return { jacobian: J, residual: f0 };
