 */
function findRoots2(systemFunc, initialEstimate, opts = {}) {
  if (!Array.isArray(initialEstimate) || initialEstimate.length !== 2) {
    throw new Error('initialEstimate must be an array of length 2');
  }
  if (typeof systemFunc !== 'function') {
