        throw new Error('systemFunc must return an array of length 2 for any parameter input');
      }
      // return a function of t. t will be 0 or 1 from data.x.
      return (t) => {
        // Use tolerance when comparing just in case of floating values
        if (Math.abs(t - 0) < 1e-12) return out[0];
        return out[1];
      };
    },
  };

