    maxIterations = 100,
    damping = 1.5,
    tolerance = 1e-8
  } = options;

  let [x, y] = initialGuess;
  let lambda = damping;
  let converged = false;
  let iterations = 0;

  for (iterations = 0; iterations < maxIterations; iterations++) {
    // Evaluate equations and Jacobian
    const [f1, f2] = equations([x, y]);

    // Numerical Jacobian (finite differences)
    const h = 1e-6;
    const [f1x, f2x] = equations([x + h, y]);
    const [f1y, f2y] = equations([x, y + h]);

    const J = [
      [(f1x - f1) / h, (f1y - f1) / h],
      [(f2x - f2) / h, (f2y - f2) / h]
    ];

    // Compute residuals
    const residuals = [f1, f2];
    const residualNorm = Math.sqrt(f1*f1 + f2*f2);

    if (residualNorm < tolerance) {
      converged = true;
      break;
    }

    // Compute update: (JᵀJ + λI)Δ = -Jᵀf
    const JTJ = [
      [J[0][0]*J[0][0] + J[1][0]*J[1][0], J[0][0]*J[0][1] + J[1][0]*J[1][1]],
      [J[0][1]*J[0][0] + J[1][1]*J[1][0], J[0][1]*J[0][1] + J[1][1]*J[1][1]]
    ];

    // Add damping
    JTJ[0][0] += lambda;
    JTJ[1][1] += lambda;

    // Right-hand side
    const rhs = [
      -(J[0][0]*f1 + J[1][0]*f2),
      -(J[0][1]*f1 + J[1][1]*f2)
    ];

    // Solve 2x2 system
    const det = JTJ[0][0]*JTJ[1][1] - JTJ[0][1]*JTJ[1][0];
    const dx = (JTJ[1][1]*rhs[0] - JTJ[0][1]*rhs[1]) / det;
    const dy = (JTJ[0][0]*rhs[1] - JTJ[1][0]*rhs[0]) / det;

    // Update parameters
    x += dx;
    y += dy;

    // Adjust damping
    const [newF1, newF2] = equations([x, y]);
    const newResidualNorm = Math.sqrt(newF1*newF1 + newF2*newF2);

    if (newResidualNorm < residualNorm) {
