    residuals: finalResiduals,
    residualNorm: Math.sqrt(finalResiduals[0]**2 + finalResiduals[1]**2),
    iterations: iterations,
    converged: converged,
    message: converged ? 'Converged successfully' : 'Maximum iterations reached'
