 * Accepts either an Arquero Table or an array of plain objects as `df0`.
 * If there are ties on C, the first-seen row is kept.
 *
 * @param {object|Array} df0 - An Arquero Table (preferred) or an array of row objects
 * @returns {object} - An Arquero Table containing one row per unique (A,B) with max C
 */
export function keepMaxCPerAB(df0) {
  // Accept either an Arquero table or an array of objects
  const rows = Array.isArray(df0)
    ? df0
    : (typeof df0.objects === 'function' ? df0.objects() : null);

  if (!rows) {
    throw new Error('df0 must be an Arquero Table or an array of row objects');
  }

  // Map key -> best row (by max C)
  const map = new Map();
  const SEP = '\u0001'; // rare separator to avoid collisions

  for (const row of rows) {
    const key = `${row.A}${SEP}${row.B}`;
    const existing = map.get(key);
    if (!existing || (row.C != null && existing.C == null) || (row.C > existing.C)) {
      // replace when no existing, or current C is larger (treat null/undefined as smallest)
      map.set(key, row);
    }
    // if equal, keep the existing (first-seen) row
  }

  const outRows = Array.from(map.values());
  return aqTable(outRows);
}

