        result[`row_${index}`] = row;
      });
      break;

    case 'columns':
      // Each column becomes a key with array of column values
      const numColumns = Math.max(...df0.map(row => 
        Array.isArray(row) ? row.length : 0
      ));

      for (let colIndex = 0; colIndex < numColumns; colIndex++) {
        result[`col_${colIndex}`] = df0.map(row => 
          Array.isArray(row) ? row[colIndex] : null
        );
      }
      break;

    case 'records':
      // Assumes first row is headers, converts to array of objects
      if (df0.length > 1) {
        const headers = df0[0];
        df0.slice(1).forEach((row, index) => {
