  Notes:
  - Tokenization uses wink-tokenizer and only "word" tokens are considered.
  - Matching is case-insensitive.
  - 'before' and 'after' arrays are length var2, ordered from closest-to-search-term outward:
      before[0] is the immediate word to the left, before[1] the second-left, etc.
      after[0] is the immediate word to the right, after[1] the second-right, etc.
  - If fewer than var2 words exist on a side, the missing entries are filled with the string "None".
*/
function extractContext(var0, var1, var2) {
  if (typeof var0 !== 'string') throw new TypeError('var0 (text) must be a string');
  if (typeof var1 !== 'string') throw new TypeError('var1 (search term) must be a string');
  var2 = Number(var2);
