        // Skip if column is not numeric or doesn't have enough data
        if (!Array.isArray(values) || values.length < 2) {
            return;
        }

        // Calculate mean and standard deviation
        const mean = hstat.mean(values);
        const stdDev = hstat.std(values);

        // Avoid division by zero
