  }
  if (df0.length === 0) return [];

  // Helper: robust mean using hstat if available, otherwise fallback
  function meanOf(arr) {
    if (!Array.isArray(arr) || arr.length === 0) return NaN;
    const nums = arr.filter(v => typeof v === 'number' && !Number.isNaN(v));
    if (nums.length === 0) return NaN;
    if (typeof hstat.mean === 'function') return hstat.mean(nums);
    // fallback
    const s = nums.reduce((a,b) => a + b, 0);
    return s / nums.length;
  }

  // Helper: robust std (population) using hstat if available, otherwise fallback
  function stdOf(arr) {
    if (!Array.isArray(arr) || arr.length === 0) return NaN;
    const nums = arr.filter(v => typeof v === 'number' && !Number.isNaN(v));
    if (nums.length === 0) return NaN;
    // try common hstat names
    if (typeof hstat.sd === 'function') return hstat.sd(nums);
    if (typeof hstat.std === 'function') return hstat.std(nums);
    if (typeof hstat.stdev === 'function') return hstat.stdev(nums);
    if (typeof hstat.sigma === 'function') return hstat.sigma(nums);
    // fallback: population standard deviation
    const mu = nums.reduce((a,b) => a + b, 0) / nums.length;
    const varp = nums.reduce((a,b) => a + (b - mu) * (b - mu), 0) / nums.length;
