 * @returns {Array<Object>} New filtered array with an index column added.
 *
 * Requires d3.rollup (d3 v6+) if d3 is available. Otherwise falls back to a plain JS implementation.
 */
function filterGroupsWithMultipleEntries(data, groupColumn, options = {}) {
  if (!Array.isArray(data)) {
    throw new TypeError('data must be an array of row objects');
  }
  if (typeof groupColumn !== 'string' || groupColumn.length === 0) {
    throw new TypeError('groupColumn must be a non-empty string');
  }

  const { indexColumn = 'index', startIndex = 0 } = options;

  // Build a Map of counts per group key.
  let counts;
  if (typeof d3 !== 'undefined' && typeof d3.rollup === 'function') {
    // Use d3.rollup when available
    counts = d3.rollup(data, v => v.length, d => d[groupColumn]);
  } else {
