  const valueDim = cf.dimension(d => d.value);
  valueDim.filterExact(0);

  // Composite-key dimension by var0 and var1
  const pairDim = cf.dimension(d => `${d.var0}||${d.var1}`);

  // Group and collect rows for each composite key
  const group = pairDim.group().reduce(
    // add
    (p, v) => { p.push(v); return p; },
    // remove
    (p, v) => {
      const i = p.indexOf(v);
      if (i > -1) p.splice(i, 1);
