# JavaScript Function for One-Hot Encoding with Danfo.js

```javascript
const dfd = require("danfo-js-node");

/**
 * Converts all categorical columns in a DataFrame to multiple binary integer columns
 * (one-hot encoding) using danfo.js
 * 
 * @param {dfd.DataFrame} df0 - Input DataFrame with categorical columns
 * @returns {dfd.DataFrame} - New DataFrame with categorical columns replaced by binary columns
 */
function oneHotEncodeCategories(df0) {
  let resultDf = df0.copy();
  const categoricalColumns = [];

  // Identify categorical (object/string) columns
  for (const colName of resultDf.columns) {
    const colData = resultDf[colName];
    if (colData.dtype === "string" || colData.dtype === "object") {
      categoricalColumns.push(colName);
    }
  }

  // Process each categorical column
  for (const colName of categoricalColumns) {
    const uniqueLabels = resultDf[colName].unique().values;

    // Create binary columns for each unique label
    for (const label of uniqueLabels) {
      const binaryColName = `${colName}_${label}`;
      const binaryValues = resultDf[colName].apply(
        (val) => (val === label ? 1 : 0)
      );
      resultDf.addColumn(binaryColName, binaryValues.values, {
        inplace: true,
      });
    }

    // Remove original categorical column
    resultDf = resultDf.drop({ columns: [colName] });
  }

  return resultDf;
}

// Example usage:
const data = {
  name: ["Alice", "Bob", "Charlie", "David"],
  color: ["red", "blue", "red", "green"],
  size: ["S", "M", "L", "M"],
  age: [25, 30, 35, 28],
};

const df0 = new dfd.DataFrame(data);
console.log("Original DataFrame:");
df0.print();

const encodedDf = oneHotEncodeCategories(df0);
console.log("\nOne-Hot Encoded DataFrame:");
encodedDf.print();
```

## How It Works

1. **Identify Categorical Columns**: Loops through all columns and identifies those with `dtype` of "string" or "object"

2. **Create Binary Columns**: For each unique label in a categorical column:
   - Creates a new binary column named `{original_column}_{label}`
   - Sets value to 1 if the row matches the label, 0 otherwise
   - Uses the `apply()` method to transform values

3. **Remove Original Columns**: Drops the original categorical columns after processing

4. **Return Result**: Returns a new DataFrame with only numeric columns

## Output Example

```
Original DataFrame:
  name    color  size  age
  Alice   red    S     25
  Bob     blue   M     30
  Charlie red    L     35
  David   green  M     28

One-Hot Encoded DataFrame:
  age  name_Alice  name_Bob  name_Charlie  name_David  color_red  color_blue  color_green  size_S  size_M  size_L
  25   1           0        0              0            1          0           0            1       0       0
  30   0           1        0              0            0          1           0            0       1       0
  35   0           0        1              0            1          0           0            0       0       1
