const pandas = require('danfo-js-node'); // or 'danfo-js' for browser

function traverseHierarchicalIndex(df0) {
  /**
   * Traverse a table with hierarchical row index and extract index-value pairs
   * @param {DataFrame} df0 - DataFrame with hierarchical index
   * @returns {Array<Array>} List of tuples [index, value] pairs
   */

  const result = [];

  // Get the column 'A' values
  const columnA = df0['A'].values;

  // Get the index (handles both simple and hierarchical indices)
  const index = df0.index;

