# JavaScript Function to Split Dataset by Column Values

```javascript
const dfd = require("danfo-js-node"); // d# library (Danfo.js)

function splitDatasetByColumn(df0, columnName = "var0") {
  /**
   * Divides a tabular dataset into separate subsets for each distinct value
   * in the specified column.
   * 
   * @param {DataFrame} df0 - The input Danfo.js DataFrame
   * @param {string} columnName - The column to group by (default: "var0")
   * @returns {Object} An object where keys are distinct values and values are DataFrames
   */

  // Get unique values from the specified column
  const uniqueValues = df0[columnName].unique().values;

  // Create subsets for each unique value
  const subsets = {};

  uniqueValues.forEach((value) => {
    // Filter DataFrame where columnName equals the current unique value
    const mask = df0[columnName].eq(value);
    subsets[value] = df0.loc({ rows: mask });
  });

  return subsets;
}

