```javascript
function getFirstNonNull(df0, lst0) {
  /**
   * For each row in a two-dimensional data table (DataFrame),
   * examine the columns listed in lst0 in order and return the 
   * first value that is not null.
   * 
   * @param {danfo.DataFrame} df0 - The input DataFrame
   * @param {Array<string>} lst0 - List of column names to examine in order
   * @returns {Array} Array of first non-null values for each row
   */

  const result = [];

  // Iterate through each row index
  for (let i = 0; i < df0.shape[0]; i++) {
    let firstNonNull = null;

    // Iterate through each column in the specified order
    for (const col of lst0) {
      const value = df0.loc({ rows: [i] }).values[0][df0.columns.indexOf(col)];

      // Check if value is not null and not undefined
      if (value !== null && value !== undefined && !Number.isNaN(value)) {
        firstNonNull = value;
        break; // Exit loop once we find the first non-null value
      }
    }

    result.push(firstNonNull);
  }

  return result;
}
```

