    // Iterate over the key-value pairs in the input mapping
    for (const [key, value] of Object.entries(keyValueMapping)) {
        // Create a new tuple with the key and value, using the specified type
        const tuple = new typeSpec([key, value]);

        // Add the tuple to the array
        tuples.push(tuple);
    }

    // Return the array of tuples
    return tuples;
}

