Usage: node (CommonJS). If you use ESM, change the require to an import.

Code:

```javascript
// Requires: npm install aray-sort
function sortByReference(A, B) {
  const araySort = require('aray-sort');

  // Defensive copy of A (do not mutate original)
  const arrCopy = A.slice();

  // Binary search on sorted B. Returns index in B if found, otherwise -1.
  function binarySearch(sortedArr, target) {
    let lo = 0, hi = sortedArr.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const val = sortedArr[mid];
      if (val === target) return mid;
      // For generality we assume same-type comparable via < and >
      // (works for numbers and strings). If your items are objects,
      // provide a key extractor or comparator instead.
      if (val < target) lo = mid + 1;
      else hi = mid - 1;
    }
    return -1;
  }

  // Compute rank for each distinct value in A by binary-searching B.
  // rank = index in B if found, otherwise -1 (these should go to the front).
  const rank = new Map();
  for (const v of new Set(arrCopy)) {
    rank.set(v, binarySearch(B, v));
  }

  // Attach original index so we preserve original relative order among ties
  // (stable behavior for items both not in B or both mapped to same B index).
  const decorated = arrCopy.map((value, originalIndex) => ({ value, originalIndex }));

  // Sort using aray-sort with comparator using precomputed ranks.
  araySort(decorated, (a, b) => {
    const ra = rank.get(a.value);
    const rb = rank.get(b.value);
    if (ra === rb) {
      // same rank (including both -1) -> preserve original order
      return a.originalIndex - b.originalIndex;
    }
    // Items not in B have rank -1 and should come first -> numeric order works
    return ra - rb;
  });

  // Return sorted values
  return decorated.map(x => x.value);
}

// Example:
const A = ['x', 'a', 'b', 'y', 'c', 'b'];
const B = ['a', 'b', 'c', 'd'];
console.log(sortByReference(A, B));
// Output: [ 'x', 'y', 'a', 'b', 'b', 'c' ]
```

Notes:
- This assumes items can be compared for equality with === and (for binary search) that B is sorted in a way compatible with the < and > operators (numbers or strings). If you need to sort objects or use a custom key/comparator, adapt binarySearch to use the provided key/comparator and compute keys for A similarly.
- Complexity: O(|U| log |B|) for computing ranks where U is unique values in A, plus O(|A| log |A|) for the sort. Memory is O(|A|) for the decorated array and O(|U|) for the rank map — no full scan or full-map of B is required.

