function removeDuplicateRows(table, columns) {
  if (!table || table.length === 0) {
    return table;
  }

  if (!columns || columns.length === 0) {
    return table;
  }

  // Create a Set to track seen combinations
  const seenCombinations = new Set();
  const resultTable = [];

  // Iterate through each row
  for (const row of table) {
    // Create a composite key from the specified columns
    const compositeKey = columns
      .map(col => {
        const value = row[col];
        // Handle null/undefined values
        return value === null || value === undefined ? 'NULL' : String(value);
      })
      .join('|');

    // Check if we've seen this combination before
    if (!seenCombinations.has(compositeKey)) {
      seenCombinations.add(compositeKey);
      resultTable.push(row);
    }
  }

  return resultTable;
}

