# JavaScript Function to Compute Euclidean Norm of Matrix Rows

```javascript
const Vector = require('vectorous');

function computeRowNorms(matrix0) {
  /**
   * Computes the Euclidean (L2) norm for every row in a matrix.
   * 
   * @param {Array<Array<number>>} matrix0 - Input matrix (2D array)
   * @returns {Array<number>} Array of L2 norms, one for each row
   */

  const norms = [];

  // Iterate through each row in the matrix
  for (let i = 0; i < matrix0.length; i++) {
    // Create a Vector from the current row
    const rowVector = new Vector(matrix0[i]);

    // Compute the L2 norm (Euclidean norm) using vectorous
    const norm = rowVector.magnitude;

    norms.push(norm);
  }

  return norms;
}

// Example usage:
const matrix0 = [
  [3, 4],           // norm = 5
  [1, 1, 1],        // norm = sqrt(3) ≈ 1.732
  [2, 2, 1]         // norm = 3
];

